import React, { useState } from 'react';
import styles from '../css/Weather.module.css';

const Weather = () => {
  const [city, setCity] = useState('');
  const [weatherData, setWeatherData] = useState(null);

  const API_KEY = '7ac5efbe309f3e7a20018760eb67b567';

  // 한국어 도시명 -> 영어로 변환 (예시)
  const translateCityName = (cityName) => {
    const cityMap = {
      '서울': 'Seoul',
      '부산': 'Busan',
      '대구': 'Daegu',
      '인천': 'Incheon',
      // 추가 도시 매핑...
    };
    return cityMap[cityName] || cityName; // 매핑되지 않으면 원래 도시명 사용
  };

  const fetchWeather = async () => {
    if (!city) {
      alert('도시 이름을 입력하세요.');
      return;
    }

    const translatedCity = translateCityName(city);

    try {
      const response = await fetch(
        `https://api.openweathermap.org/data/2.5/weather?q=${translatedCity}&appid=${API_KEY}&units=metric&lang=kr`
      );
      const data = await response.json();
      console.log(data); // 데이터를 콘솔에 출력
      if (data.cod === 200) {
        setWeatherData(data);
      } else {
        alert('도시를 찾을 수 없습니다!');
        setWeatherData(null);
      }
    } catch (error) {
      console.error('날씨 데이터를 가져오는 중 오류가 발생했습니다:', error);
    }
  };

  return ( // 반드시 return 추가
    <div className={styles.container}>
      <h2>날씨 정보</h2>
      <input
        className={styles.input}
        type="text"
        placeholder="도시 이름 입력"
        value={city}
        onChange={(e) => setCity(e.target.value)}
      />
      <button className={styles.button} onClick={fetchWeather}>날씨 정보 가져오기</button>
      {weatherData && (
        <div className={styles['weather-info']}>
          <p>온도: {weatherData.main.temp}°C</p>
          <p>날씨: {weatherData.weather[0].description}</p>
        </div>
      )}
    </div>
  );
};

export default Weather;
